fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Pre-allocate a new vector with enough capacity for all elements plus one
    let mut result = Vec::with_capacity(a.len() + 1);

    // Copy over all elements from the original vector
    result.extend_from_slice(a);

    // Append the new element
    result.push(b);

    result
}

